#!/usr/bin/env python3
"""Org guard hook (generated by agent-org). Usage: org_guard.py bash | edit | stop

  bash  PreToolUse(Bash): refuse commands that bypass the org's gates or corrupt shared state.
        Always blocked: `gh pr merge --admin`, non-lease force pushes, `--no-verify`.
        Blocked only while an org run is active (the CEO's marker file, or AGENT_ORG_RUN=1 in
        headless runs): merging below L3, pushing to the base branch, and `git stash`. A human's
        own sessions in the repo are never restricted by the org's autonomy level.
  edit  PreToolUse(Edit|Write|MultiEdit): refuse edits to files that define a quality gate, and
        always to the org's own control files (CONTROL_FILES), whatever org.json says.
  stop  Stop: run the configured cheap check once per edit batch and surface its errors.

Exit 2 blocks the tool call and sends stderr to the model. Policy lives in
.claude/ceo/org.json, so tightening or loosening the guard is a reviewed config change,
not an edit to this script. Any internal error exits 0: the guard never breaks a session.
"""
import json
import os
import re
import subprocess
import sys
import time

ROOT = os.environ.get("CLAUDE_PROJECT_DIR") or os.getcwd()

# A command position: start of string, a shell separator, or a newline. Anchoring here keeps
# the guard from firing on its own patterns quoted inside a commit message or PR body.
CMD = r"(?:\A|[;&|(]|\n)\s*"

# Files that control the org itself: the autonomy level, the guard's own policy and wiring.
# Hard-coded rather than read from org.json, so an agent can't unprotect them by editing the list.
CONTROL_FILES = (".claude/ceo/org.json", ".claude/ceo/AUTONOMY.md", ".claude/ceo/DEMOTED",
                 ".claude/settings.json")
CONTROL_DIRS = (".claude/hooks/",)
LEVELS = ("L0", "L1", "L2", "L3", "L4")


def load_org():
    try:
        with open(os.path.join(ROOT, ".claude", "ceo", "org.json")) as f:
            return json.load(f)
    except (OSError, ValueError):
        return {}


RUN_MARKER_MAX_AGE = 12 * 3600  # a crashed run's marker stops binding after 12h


def org_run_active():
    if os.environ.get("AGENT_ORG_RUN") == "1":
        return True
    marker = os.path.join(ROOT, ".claude", "ceo", ".cache", "run-active")
    try:
        return time.time() - os.path.getmtime(marker) < RUN_MARKER_MAX_AGE
    except OSError:
        return False


def is_control_file(rel):
    rel = rel.replace(os.sep, "/")
    return rel in CONTROL_FILES or rel.startswith(CONTROL_DIRS)


def effective_level(org):
    """org.json's level, lowered by .claude/ceo/DEMOTED if present. The CEO demotes by creating
    DEMOTED (creating is allowed, editing it is not), so an agent can lower the level, never raise it."""
    level = str(org.get("autonomy_level", "L0")).upper()
    try:
        with open(os.path.join(ROOT, ".claude", "ceo", "DEMOTED")) as f:
            demoted = f.read().strip().upper()[:2]
    except OSError:
        return level
    return min(level, demoted) if demoted in LEVELS else "L0"


def block(msg):
    sys.stderr.write("BLOCKED by .claude/hooks/org_guard.py: " + msg + "\n")
    return 2


def check_bash(cmd, org):
    base = re.escape(org.get("base_branch", "main"))
    # Always: these are never right, whoever is driving.
    if re.search(CMD + r"gh\s+pr\s+merge\b[^\n;&|]*--admin\b", cmd):
        return block("`gh pr merge --admin` bypasses required checks. Fix the red condition "
                     "or hand the PR to the human.")
    if re.search(CMD + r"git\s+push\b[^\n;&|]*(?:--force(?!-with-lease)\b|\s-f\b)", cmd):
        return block("force-pushing is not allowed (use --force-with-lease on your own work branch).")
    if re.search(CMD + r"git\s+(?:commit|push|merge)\b[^\n;&|]*--no-verify\b", cmd):
        return block("--no-verify skips the repo's own hooks. Fix what the hook reports.")
    if not org_run_active():
        return 0
    # Only during an org run: the autonomy level and shared-tree rules bind the org, not the human.
    level = effective_level(org)
    if level < "L3" and re.search(CMD + r"gh\s+pr\s+merge\b", cmd):
        return block(f"autonomy_level is {level}: below L3 the human merges. Report the PR URL "
                     "instead. Only the human raises the level (.claude/ceo/org.json).")
    control = "|".join(re.escape(p) for p in CONTROL_FILES + CONTROL_DIRS)
    if re.search(CMD + r"(?:[^\n;&|]*>>?\s*|(?:sed|perl)\s+[^\n;&|]*-i\b[^\n;&|]*|(?:tee|cp|mv|rm|truncate)\b[^\n;&|]*)"
                 r"(?:\./)?(?:" + control + ")", cmd):
        return block("that command writes a file that controls the org itself (autonomy level, guard "
                     "policy or hooks). Only the human edits it. To demote, create .claude/ceo/DEMOTED.")
    if re.search(CMD + r"git\s+push\b[^\n;&|]*\b" + base + r"\b[^\n;&|]*--force-with-lease", cmd) or \
            re.search(CMD + r"git\s+push\b[^\n;&|]*\s(?:origin\s+)?(?:HEAD:)?" + base + r"\s*(?:$|[;&|\n])", cmd):
        return block("an org run never pushes to the base branch. Push a work branch and open a PR.")
    if org.get("guard", {}).get("block_stash", True) and \
            re.search(CMD + r"git\s+stash\b(?!\s+(?:list|show)\b)", cmd):
        return block("git stash is shared across every worktree and session, and a stash taken "
                     "while an agent runs removes work from under it. Use `git show HEAD:<path>` "
                     "for a baseline, or a WIP commit to set work aside.")
    return 0


def check_edit(tool_input, org):
    path = tool_input.get("file_path") or ""
    if not path or not os.path.exists(path):
        return 0  # creating a file is fine
    rel = os.path.relpath(os.path.abspath(path), ROOT)
    allow = os.path.join(ROOT, ".claude", "ceo", "ALLOW_GATE_EDITS")
    if is_control_file(rel):
        if os.path.exists(allow):
            return 0
        return block(f"{rel} controls the org itself (autonomy level, guard policy or hooks). Only "
                     "the human edits it; put the change under 'Needs a human' in the backlog. To "
                     "demote after a revert, create .claude/ceo/DEMOTED containing the new level.")
    for gate_file in org.get("gate_files", []):
        if rel == gate_file or os.path.basename(rel) == gate_file:
            if os.path.exists(allow):
                return 0
            return block(f"{rel} defines a quality gate. Fix the code so the existing gate "
                         "passes. If the item genuinely needs to change the gate (e.g. to ADD a "
                         "check), put it under 'Needs a human' in the backlog: the human enables "
                         "gate edits for one run with `touch .claude/ceo/ALLOW_GATE_EDITS`. "
                         "Agents never create that file.")
    return 0


def newest_mtime(dirs, exts):
    newest = 0.0
    for d in dirs:
        for dirpath, dirnames, filenames in os.walk(os.path.join(ROOT, d)):
            dirnames[:] = [n for n in dirnames if n not in ("node_modules", ".git", "dist", "build")]
            for name in filenames:
                if name.endswith(tuple(exts)):
                    newest = max(newest, os.path.getmtime(os.path.join(dirpath, name)))
    return newest


def check_stop(org):
    cfg = org.get("guard", {}).get("stop_check", {})
    cmd = cfg.get("cmd")
    if not cmd:
        return 0
    stamp_dir = os.path.join(ROOT, ".claude", "ceo", ".cache")
    stamp = os.path.join(stamp_dir, "stop-check-stamp")
    last = os.path.getmtime(stamp) if os.path.exists(stamp) else 0.0
    if newest_mtime(cfg.get("watch", ["src"]), cfg.get("extensions", [".ts", ".tsx"])) <= last:
        return 0
    os.makedirs(stamp_dir, exist_ok=True)
    open(stamp, "w").close()  # stamp first: one nudge per edit batch, never a loop
    res = subprocess.run(cmd, shell=True, cwd=ROOT, capture_output=True, text=True, timeout=110)
    if res.returncode == 0:
        return 0
    tail = "\n".join((res.stdout + res.stderr).strip().splitlines()[-20:])
    sys.stderr.write(f"`{cmd}` failed after your edits:\n{tail}\n")
    return 2


def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else ""
    try:
        payload = json.load(sys.stdin) if not sys.stdin.isatty() else {}
    except ValueError:
        payload = {}
    org = load_org()
    tool_input = payload.get("tool_input") or {}
    try:
        if mode == "bash":
            return check_bash(tool_input.get("command") or "", org)
        if mode == "edit":
            return check_edit(tool_input, org)
        if mode == "stop":
            return check_stop(org)
    except Exception as e:  # never break the session, but never fail silently either
        sys.stderr.write(f"[org_guard {mode}] skipped: {e}\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
